To find which axis to flip, we look at the penetration depth on each axis.
The smallest penetration depth usually indicates the side that was hit.

```javascript
function resolveBrickCollision(state, brick) {
  const { ball } = state;

  // Calculate overlap on each axis
  const overlapX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
  const overlapY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));

  if (overlapX < overlapY) {
    // Hit from side
    ball.vx = -Math.sign(ball.vx) * Math.abs(ball.vx); // Flip vx
    // Reposition ball
    if (ball.vx > 0) ball.x = brick.x - ball.r; else ball.x = brick.x + brick.w + ball.r;
    // Wait, the sign of vx was’t flipped yet.
  } else {
    // Hit from top/bottom
    ball.vy = -Math.sign(ball.vy) * Math.abs(ball.vy);
    // Reposition
    if (ball.vy > 0) ball.y = brick.y - brick.h - ball.r; else ball.y = brick.y + brick.h + ball.r;
  }
}
