// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Sub-stepping to prevent tunneling (D5)
  const subSteps = 4;
  const sdt = dt / subSteps;

  for (let i = 0; i < subSteps; i++) {
    ball.x += ball.vx * sdt;
    ball.y += ball.vy * sdt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0;
    }

    // Bricks
    for (const brick of state.bricks) {
      if (!brick.alive) continue;

      if (collides(ball, brick)) {
        const overlapLeft = (ball.x + ball.r) - brick.x;
        const overlapRight = (brick.x + brick.w) - (ball.x - ball.r);
        const overlapTop = (ball.y + ball.r) - brick.y;
        const overlapBottom = (brick.y + brick.h) - (ball.y - ball.r);

        const minOverlap = Math.min(overlapLeft, overlapRight, overlapTop, overlapBottom);

        if (minOverlap === overlapLeft) {
          ball.vx = -Math.abs(ball.vx);
          ball.x = brick.x - ball.r;
        } else if (minOverlap === overlapRight) {
          ball.vx = Math.abs(ball.vx);
          ball.x = brick.x + brick.w + ball.r;
        } else if (minOverlap === overlapTop) {
          ball.vy = Math.abs(ball.vy);
          ball.y = brick.y - ball.r;
        } else {
          ball.vy = -Math.abs(ball.vy);
          ball.y = brick.y + brick.h + ball.r;
        }

        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
        // To avoid double-inverting in the same sub-step (though brick is now dead),
        // we could break here. But since the brick is dead, other bricks
        // in the same row/col will still be processed if they overlap.
        // For better seams handling, we can break the brick loop.
        break;
      }
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

