test('D2: Ball should bounce off side of brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + 2; // Now well inside the field
  state.ball.y = brick.y + 10;
  state.ball.vx = -200; // Moving LEFT towards the brick's right side? No, let's move RIGHT.
  state.ball.x = brick.x - 10; // Just left of the brick
  state.ball.vx = 200;
  state.ball.vy = 0;
  step(state, 0.01);
  assert.equal(state.ball.vx, -200);
  assert.equal(state.ball.vy, 0);
});

